{
  "name": "SHFSG 超高频信号发生器",
  "name_en": "SHFSG Super-High-Frequency Signal Generator",
  "manufacturer": "Zurich Instruments",
  "description": "用于产生可编程高频信号的仪器，支持 AWG 测序器、波形存储、命令表、触发/标记配置、脉冲调制和正弦信号生成功能，常用于量子控制、微波脉冲实验和射频测试。",
  "description_en": "An instrument for generating programmable high-frequency signals. It supports an AWG sequencer, waveform memory, command tables, trigger/marker configuration, pulse modulation, and sine generation, and is commonly used for quantum control, microwave pulse experiments, and RF testing.",
  "actions": [
    {
      "action_name": "auto-factory_reset",
      "description": "恢复设备出厂默认设置。",
      "description_en": "Restore the device to factory default settings."
    },
    {
      "action_name": "auto-check_status",
      "description": "检查命令表状态。",
      "description_en": "Check the status of the command table."
    },
    {
      "action_name": "auto-load_validation_schema",
      "description": "加载命令表的验证模式。",
      "description_en": "Load the validation schema for the command table."
    },
    {
      "action_name": "auto-upload_to_device",
      "description": "将命令表上传到设备。",
      "description_en": "Upload the command table to the device."
    },
    {
      "action_name": "auto-load_from_device",
      "description": "从设备读取命令表。",
      "description_en": "Load the command table from the device."
    },
    {
      "action_name": "auto-enable_sequencer",
      "description": "启用 AWG 测序器。",
      "description_en": "Enable the AWG sequencer."
    },
    {
      "action_name": "auto-wait_done",
      "description": "等待测序器或相关操作完成。",
      "description_en": "Wait until the sequencer or related operation is complete."
    },
    {
      "action_name": "auto-compile_sequencer_program",
      "description": "编译测序器程序。",
      "description_en": "Compile the sequencer program."
    },
    {
      "action_name": "auto-load_sequencer_program",
      "description": "将测序器程序加载到设备。",
      "description_en": "Load the sequencer program onto the device."
    },
    {
      "action_name": "auto-write_to_waveform_memory",
      "description": "向波形存储器写入波形数据。",
      "description_en": "Write waveform data to waveform memory."
    },
    {
      "action_name": "auto-read_from_waveform_memory",
      "description": "从波形存储器读取波形数据。",
      "description_en": "Read waveform data from waveform memory."
    },
    {
      "action_name": "auto-configure_marker_and_trigger",
      "description": "配置标记输出和触发设置。",
      "description_en": "Configure marker outputs and trigger settings."
    },
    {
      "action_name": "auto-available_trigger_inputs",
      "description": "列出可用的触发输入。",
      "description_en": "List the available trigger inputs."
    },
    {
      "action_name": "auto-available_trigger_slopes",
      "description": "列出可用的触发边沿类型。",
      "description_en": "List the available trigger slope types."
    },
    {
      "action_name": "auto-available_marker_outputs",
      "description": "列出可用的标记输出。",
      "description_en": "List the available marker outputs."
    },
    {
      "action_name": "auto-configure_channel",
      "description": "配置信号发生器通道。",
      "description_en": "Configure the signal generator channel."
    },
    {
      "action_name": "auto-configure_pulse_modulation",
      "description": "配置脉冲调制参数。",
      "description_en": "Configure pulse modulation settings."
    },
    {
      "action_name": "auto-configure_sine_generation",
      "description": "配置正弦信号生成功能。",
      "description_en": "Configure sine signal generation."
    },
    {
      "action_name": "auto-awg_modulation_freq",
      "description": "获取或设置 AWG 调制频率。",
      "description_en": "Get or set the AWG modulation frequency."
    }
  ],
  "tag_hints": [
    "signal generation",
    "AWG sequencer",
    "waveform memory",
    "trigger and marker I/O",
    "pulse modulation",
    "quantum control",
    "RF and microwave experiments"
  ]
}

